      "type": "dict",
      "properties": {
        "folder": {
          "type": "string",
          "description": "The folder of the directory to change to. You can only change one folder at a time. "
        }
      },
      "required": [
        "folder"
      ]
    },
    "response": {
      "type": "dict",
      "properties": {
        "current_working_directory": {
          "type": "string",
          "description": "The new current working directory path."
        }
      }
    }
  },
  {
